if(kind==='furniture'){html+=`<label class="inline"><input data-prop="blocksMovement" type="checkbox" ${o.blocksMovement?'checked':''}> Include in route obstacles</label><p>Furniture is visible and editable. It never divides rooms or changes gross room area. This option only changes walkable routes.</p>`;}
if(kind==='context')html+='<p>Context is separate from room detection. Courtyards, exterior and voids are excluded from indoor area / routing; projected geometry is reference only.</p>';
if(kind==='candidate')html+=`<p>Proposed ${esc(o.kind)}. Drag the two jamb points to correct the position. It does not connect spaces until confirmed.</p><label>Measured clear opening width (${unit()})<input id="candidate-width" type="number" min="0.01" value="${nfmt(dist(...o.points.slice(0,2)))}"></label><div class="candidate-actions"><button id="confirm-door">Confirm interior door / passage</button><button id="confirm-exit">Confirm exit to ${floor().elevation===0?'site':'vertical circulation'}</button></div>`;
if(kind==='room'){html+=`<label>Spatial type<select data-prop="role">${['room','corridor','lobby'].map(k=>`<option value="${k}" ${(o.role||'room')===k?'selected':''}>${k}</option>`).join('')}</select></label>`;if(o.role==='corridor')html+=propertyInput(`Measured clear width (${unit()}, optional)`,'clearWidth',o.clearWidth>0?nfmt(o.clearWidth):'','number','min="0.01" step="0.1"')+'<p class="small">Leave blank for a boundary-based width estimate. Confirm inner clear faces. Circulation is not counted as a second group of room occupants.</p>';html+=propertyInput(`Program area target (${p.units==='ft'?'sf':'m²'}, optional)`,'targetArea',o.targetArea==null?'':(o.targetArea/(p.units==='ft'?SF:1)).toFixed(1),'number','min="0" step="1"');html+=`<label>Space function<select data-prop="function">${Object.entries(functions).map(([k,v])=>`<option value="${k}" ${k===o.function?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Occupancy classification<select data-prop="group">${['A','B','E','M'].map(v=>`<option ${o.group===v?'selected':''}>${v}</option>`).join('')}</select></label>`+propertyInput('Load factor (sf/person)','factor',o.factor,'number','min="1"')+`<label>Area basis<select data-prop="basis"><option ${o.basis==='net'?'selected':''}>net</option><option ${o.basis==='gross'?'selected':''}>gross</option></select></label><label class="inline"><input type="checkbox" data-prop="areaConfirmed" ${o.areaConfirmed?'checked':''}> I checked the area basis</label><p class="small">Area ${(roomArea(p,p.activeFloor,o)/SF).toFixed(0)} sf (${roomArea(p,p.activeFloor,o).toFixed(1)} m²)<br>Calculated load ${roomLoad(p,p.activeFloor,o).occupants} people${o.role==='corridor'?' (circulation; served room loads are counted downstream)':''}</p>`;}
if(kind==='void'){const base=p.floors.find(f=>f.id===o.baseFloorId),top=p.floors.find(f=>f.id===o.throughFloorId),options=(key)=>p.floors.map(f=>`<option value="${f.id}" ${o[key]===f.id?'selected':''}>${esc(f.name)} · ${fmt(f.elevation)}</option>`).join('');html+=`<label>Lowest occupied floor<select data-prop="baseFloorId">${options('baseFloorId')}</select></label><label>Highest floor WITHOUT a slab<select data-prop="throughFloorId">${options('throughFloorId')}</select></label><p class="small">The base retains its floor. Openings are cut in every level above it through the chosen top level. Shared XY footprint on all affected floors. Upper-floor routes avoid the opening; room areas and loads exclude it.</p><p class="small">${base&&top?p.floors.filter(f=>f.elevation>=base.elevation&&f.elevation<=top.elevation).length+' levels in the space':''} · footprint ${(area(o.points)/(p.units==='ft'?SF:1)).toFixed(1)} ${p.units==='ft'?'sf':'m²'}.<br>Smoke control, guards, atrium separation and structural support require separate review.</p>`;}
if(kind==='door')html+=`<label class="inline"><input type="checkbox" data-prop="exit" ${o.exit?'checked':''}> This is an exit</label>${o.exit?`<label>Exit leads to<select data-prop="discharge"><option value="site" ${o.discharge==='site'?'selected':''}>Site / exit discharge</option><option value="none" ${o.discharge!=='site'?'selected':''}>Requires connection review</option></select></label>`:''}<p class="small">${o.exit&&floor().elevation===0?'This is the same exit shown on the ground-floor + site view. Moving it updates both route segments. ':''}Opening width is measured clear. Door swing, hardware and fire protection require review.</p>`;
