function drawImportPreview(canvas,segments,walls){
 const c=canvas.getContext('2d'),b=bounds(segments.flatMap(s=>[s.a,s.b])),s=Math.min((canvas.width-30)/Math.max(.1,b.maxX-b.minX),(canvas.height-30)/Math.max(.1,b.maxY-b.minY)),point=q=>({x:canvas.width/2+(q.x-(b.minX+b.maxX)/2)*s,y:canvas.height/2-(q.y-(b.minY+b.maxY)/2)*s});c.clearRect(0,0,canvas.width,canvas.height);
 for(const [list,color,width]of [[segments,'#a4b0ab',1],[walls,'#268266',2]])for(const line of list){const a=point(line.a),b=point(line.b);c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
}
function wallOptions(){return `<div class="formgrid"><label>Single-line wall thickness (${unit()})<input id="wall-thickness" type="number" step="0.01" min="0.01" value="${nfmt(.15)}"></label><label>Double-line minimum thickness (${unit()})<input id="wall-min" type="number" step="0.01" min="0.01" value="${nfmt(.07)}"></label><label>Double-line maximum thickness (${unit()})<input id="wall-max" type="number" step="0.01" min="0.01" value="${nfmt(.6)}"></label></div>`;}
