function cadToWalls(id){
 const segs=target().cad.filter(s=>s.layer===id);if(segs.length>1500)return toast('Select a cleaner layer or trace its walls using Osnap. Maximum 1,500 segments per conversion.');
 modal('Convert reference layer to walls',`<label>Wall linework<select id="layer-wall-mode"><option value="single">Single-line centerlines</option><option value="double">Double-line faces</option></select></label>${wallOptions()}<canvas id="cad-preview" class="cad-preview" width="560" height="220"></canvas><p id="layer-summary"></p><label class="inline"><input id="layer-reviewed" type="checkbox"> I reviewed the proposed green walls and their thickness</label><p>Original CAD stays as reference. Door symbols do not create openings.</p><button id="convert-walls" class="primary">Convert reviewed walls</button>`);let walls=[];
 const refresh=()=>{try{if($('#layer-wall-mode').value==='double'){const r=pairWallFaces(segs,{minThickness:Number($('#wall-min').value)*meter(),maxThickness:Number($('#wall-max').value)*meter()});walls=r.pairs;$('#layer-summary').textContent=walls.length+' paired walls; '+r.unpaired.length+' unmatched faces remain reference.';}else{const thickness=Number($('#wall-thickness').value)*meter();if(!(thickness>0))throw Error('Enter a positive thickness.');walls=segs.map(s=>({...s,thickness}));$('#layer-summary').textContent=walls.length+' centerline walls.';}$('#layer-reviewed').checked=false;drawImportPreview($('#cad-preview'),segs,walls);$('#convert-walls').disabled=!walls.length;}catch(e){walls=[];$('#layer-summary').textContent=e.message;$('#convert-walls').disabled=true;}};
 for(const el of [$('#layer-wall-mode'),...$$('#modal-content input[type=number]')])el.onchange=refresh;$('#convert-walls').onclick=()=>{if(!$('#layer-reviewed').checked)return toast('Review and confirm the preview first.');remember();floor().walls.push(...walls.map(w=>({id:uid(),a:{...w.a},b:{...w.b},thickness:w.thickness})));const layer=target().layers.find(l=>l.id===id);if(layer)layer.visible=false;$('#modal').close();change();if(!floor().rooms.length)detectRoomDialog();};refresh();
}

function guide(){modal('Design, test, improve',`<p><a href="https://github.com/doubleteng/tengteng/tree/main/teaching/egress" target="_blank" rel="noopener">Application source</a> · <a href="./THIRD_PARTY.md" target="_blank" rel="noopener">Licenses + CAD decoder source</a></p><div class="help-step"><b>1</b><div><strong>Draw or import</strong><p>Start with a floor boundary, then add rooms, walls and doors. Import DWG, DXF or 2D Rhino linework; choose layers and confirm units. Calibrate PDFs and images, then use Trace image / PDF linework to review extracted linework and create walls.</p></div></div><div class="help-step"><b>2</b><div><strong>Connect the whole journey</strong><p>Use a shared XY origin and a reference-floor overlay. Stair links need matching names and overlapping footprints. Multi-height space cuts upper-floor slabs from its occupied base through the selected top floor. On the site, draw walkable areas, obstacles and real public-way connections. Mark assembly points separately.</p></div></div><div class="help-step"><b>3</b><div><strong>Play with the design</strong><p>Drag objects or their handles. Checks update after each edit. Use All floors to edit linked plans side by side; the ground floor and site share one view, Play to follow paths, and a baseline to compare changes.</p></div></div><div class="help-step"><b>4</b><div><strong>Explain the result</strong><p>Click a check to find the issue. Trace common paths and dead ends, confirm the net/gross area basis, and save a PDF report on your device with the assumptions and unresolved checks. Edit the recognized rooms, walls and doors directly in the lab; area, occupant loads and route checks update after each change. No account or API key is needed.</p></div></div><div class="callout">Enter: finish shape · Escape: cancel · Delete: remove selection · Ctrl/Cmd+Z: undo · Ctrl/Cmd+S: save file · Right-button drag: pan · wheel: zoom at cursor · Shift / F8: Ortho · F9: Grid · Alt: bypass snap<br>Visibility controls affect display only. Hidden analysis walls and obstacles still count.</div>${target().image?'<button id="calibrate-start">Calibrate image using two points</button>':''}`);if($('#calibrate-start'))$('#calibrate-start').onclick=()=>{$('#modal').close();setTool('calibrate');$('#hint').textContent='Click the two ends of a known distance on the image.';};}
$('#help-btn').onclick=guide;
$('#scope-btn').onclick=()=>modal('Check scope + sources',`<p><b>IBC 2021 educational subset.</b> The app checks selected A, B, E and M cases. It does not certify Michigan Building Code compliance or apply local amendments automatically.</p><ul><li>Sampled exit-access travel and geometric connectivity</li><li>Occupant-load calculations using the selected function and area basis</li><li>Door clear widths, basic exit separation and load-based doorway counts</li><li>Linked protected-stair assumptions and ground-floor connections to the public way</li><li>Manually traced common paths and dead ends</li><li>Selected ADA walking-route width/slope checks and pedestrian–vehicle crossing review</li></ul><p>Fire ratings, hardware, intervening-space legality, mixed occupancy, fixed-seat assembly, full stair/ramp design, corridor minima, discharge capacity and accessible means of egress remain review items. Route playback does not predict evacuation time.</p><div class="source-list"><p><a href="${sources.ibc}" target="_blank" rel="noopener">ICC · 2021 IBC Means of Egress ↗</a><br><a href="${sources.ada}" target="_blank" rel="noopener">U.S. Access Board · ADA Chapter 4 ↗</a><br><a href="https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books" target="_blank" rel="noopener">Michigan adopted codes ↗</a><br><a href="./THIRD_PARTY.md" target="_blank">CAD decoder licenses + source ↗</a></p></div>`);
$('#report-btn').onclick=()=>{if(!analysis||analyzedRevision!==revision)return toast('Wait for the current design checks before exporting.');const image=canvas.toDataURL('image/png'),complete=analysis.complete;const html=`<!doctype html><html><head><title>${esc(p.name)} — Egress + Site report</title><style>body{font:12px/1.6 Arial,sans-serif;color:#26352f;margin:35px}h1{font-size:26px}h2{margin-top:28px;border-bottom:1px solid #ccc}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #ddd;padding:7px;text-align:left;vertical-align:top}th{background:#edf2ea}.fail{color:#a54035}.review{color:#937023}.pass{color:#2c6a49}img{width:100%;max-height:550px;object-fit:contain}button{padding:12px}@media print{button,.print-note{display:none}h2,h3{break-after:avoid}tr{break-inside:avoid}}</style></head><body><button onclick="window.print()">Save as PDF on this device</button><p class="print-note">Choose “Save as PDF” in the print window. No account or cloud storage is needed. Keep editing your design in the lab: moving walls, changing room use and adjusting doors updates the analysis. This PDF records the current version.</p><h1>${esc(p.name)}</h1><p>Egress + Site Lab · ${new Date().toLocaleString()}<br>IBC 2021 teaching subset · ${p.settings.sprinkler?'NFPA 13 throughout assumed':'No full sprinkler allowance'} · ${p.settings.voice?'Voice/alarm assumed':'No voice/alarm reduction'}<br>Results refer to the modeled geometry and assumptions; they are not a complete code determination.</p><img src="${image}" alt="Design overview"><h2>Complete building-to-site routes</h2><table><tr><th>Floor / room</th><th>Connection</th><th>Total route</th></tr>${complete.map(r=>`<tr><td>${esc(p.floors[r.floor].name)} / ${esc(r.name)}</td><td>${r.complete?'Connected to public way':'Connection requires review'}</td><td>${fmt(r.distance)} (includes user-entered stair travel)</td></tr>`).join('')}</table>${analysis.floors.map((r,i)=>`<h2>${esc(p.floors[i].name)}</h2><p>${r.total} design occupants · ${r.exits} identified exits · analysis grid ${fmt(r.gridStep||0)}</p><h3>Room area → design occupant load</h3><table><tr><th>Space / use</th><th>Area and basis</th><th>Load factor</th><th>Calculated people</th><th>Input review</th></tr>${r.rooms.map(o=>`<tr><td>${esc(o.name)}<br>${esc(o.functionLabel)}</td><td>${(o.area/SF).toFixed(1)} sf / ${o.area.toFixed(2)} m²<br>${esc(o.basis)}</td><td>${o.role==='corridor'?'No additional occupants':o.factor+' sf/person'}</td><td>${o.occupants}</td><td>${o.areaConfirmed?'Area basis confirmed':'Confirm use, net/gross basis and scale'}</td></tr>`).join('')}</table><h3>Doors, corridors and stairs → width bottlenecks</h3><p>${esc(r.capacity?.method||'Route allocation unavailable.')} Required width is the greater of the component minimum and served occupants × capacity factor. Stair requirements are evaluated per story.</p><table><tr><th>Component / source rooms</th><th>Modeled people</th><th>Provided width</th><th>Required width</th><th>Shortfall / action</th></tr>${(r.capacity?.rows||[]).map(o=>`<tr><td>${esc(o.name)} · ${esc(o.kind)}<br>${o.sources.map(esc).join(', ')}</td><td>${o.allocationKnown||o.corridorServed>0?o.load:'Unresolved'}${o.corridorServed!=null?'<br>Corridor total: '+o.corridorServed:''}</td><td>${o.available==null?'Not measured':capfmt(o.available)}<br>${esc(o.widthSource)}</td><td>${o.allocationKnown||o.corridorServed>0?capfmt(o.required,true):'Allocation needed'}<br>Minimum ${capfmt(o.minimum,true)}; ${o.factor} in/person</td><td class="${o.status}">${o.shortfall>0?'Short by '+capfmt(o.shortfall,true)+' — widen or revise allocation':'REVIEW: confirm clear width and allocation'}</td></tr>`).join('')}</table><h3>Checks and design actions</h3><table><tr><th>Status</th><th>Check</th><th>Evidence / next step</th><th>Reference</th></tr>${r.checks.map(c=>`<tr><td class="${c.status}">${c.status.toUpperCase()}</td><td>${esc(c.title)}</td><td>${esc(c.detail)}</td><td>${esc(c.ref)}</td></tr>`).join('')}</table>`).join('')}<h2>Design revision priorities</h2><p>Resolve flagged checks first. Review items identify missing inputs or unverified conditions; they do not establish a pass. Use each finding’s evidence / next step to modify the design online. Checks update automatically as room geometry, use, doors and corridors change. Export a new PDF to record the revised scheme.</p><h2>Source drawings</h2>${p.floors.map(f=>`<p>${esc(f.name)}: ${[f.image?esc(f.image.name)+'; scale '+(f.image.calibrated?'calibrated':'NOT calibrated'):'',...(f.imports||[]).map(i=>esc(i.name)+'; omitted: '+esc(JSON.stringify(i.ignored)))].filter(Boolean).join('<br>')||'Drawn in app'}</p>`).join('')}<h2>References</h2><p><a href="${sources.ibc}">ICC 2021 IBC Means of Egress</a><br><a href="${sources.ada}">ADA Chapter 4</a></p></body></html>`;const win=window.open('','_blank');if(win){win.document.open();win.document.write(html);win.document.close();}else download(new Blob([html],{type:'text/html'}),'egress-report.html');};
const vision=new VisionConnection();
const visionConfig=fetch('./vision-config.json').then(r=>{if(!r.ok)throw Error('Recognition configuration is unavailable.');return r.json();}).catch(()=>({endpoint:''}));
requestAnimationFrame(draw);restore();

function journeyPanel(x,y,w,h){ctx.fillStyle='#f1f4ec';ctx.fillRect(x,y,w,h);ctx.fillStyle='#6a846c';ctx.font='10px sans-serif';ctx.textAlign='left';ctx.fillText('CONNECTED DESIGN',x+25,y+34);ctx.font='22px sans-serif';ctx.fillStyle='#2e5b45';const n=analysis?.complete.filter(r=>r.complete).length||0,total=analysis?.complete.length||0;ctx.fillText(n+' / '+total+' routes connected',x+25,y+72);ctx.font='11px sans-serif';ctx.fillStyle='#7d8a76';ctx.fillText('Rooms → stairs → ground floor → public way',x+25,y+99);let yy=y+135;const links=[...new Set((analysis?.connections||[]).map(c=>c.link))];for(const link of links.slice(0,4)){ctx.fillStyle='#d9e6d4';ctx.fillRect(x+25,yy-12,w-50,30);ctx.fillStyle='#55774f';ctx.fillText('↕  '+link+' · linked across floors',x+36,yy+6);yy+=39;}ctx.fillStyle='#7d8a76';ctx.fillText('Try moving an exit. Watch the whole route change.',x+25,Math.min(y+h-40,yy+28));ctx.fillText('Use a baseline to compare your next design move.',x+25,Math.min(y+h-22,yy+48));}
